# Generated by Heron Brush. Run in Blender, or with blender --python this_file.py.
# Imports only this OBJ and configures its tangent-space normal maps. Existing
# scene objects remain in place; imported materials are copied before edits.
from pathlib import Path
import re
import bpy


def import_heron_obj(path):
    path = Path(path).resolve()
    records, current = {}, None
    for raw in path.with_suffix('.mtl').read_text(encoding='utf-8').splitlines():
        line = raw.strip()
        if line.startswith('newmtl '):
            current = records.setdefault(line.split(None, 1)[1], {})
        elif current is not None and line.startswith('norm '):
            value = line.split(None, 1)[1]
            match = re.match(r'-bm\s+(\S+)\s+(.*)$', value)
            current['normal'] = (float(match[1]), match[2]) if match else (1.0, value)
    before = set(bpy.data.objects)
    bpy.ops.wm.obj_import(filepath=str(path))
    imported = [obj for obj in bpy.data.objects if obj not in before]
    copies = {}
    for obj in imported:
        for slot in obj.material_slots:
            original = slot.material
            if original is None:
                continue
            name = original.name if original.name in records else re.sub(r'\.\d{3}$', '', original.name)
            config = records.get(name, {})
            if 'normal' not in config:
                continue
            if original not in copies:
                material = original.copy()
                material.use_nodes = True
                nodes, links = material.node_tree.nodes, material.node_tree.links
                shader = next((node for node in nodes if node.type == 'BSDF_PRINCIPLED'), None)
                if shader is None:
                    raise RuntimeError('No Principled shader on imported material ' + name)
                strength, image_path = config['normal']
                image = bpy.data.images.load(str(path.parent / image_path), check_existing=True)
                # Colour-space belongs to the image datablock. A separate copy keeps
                # an image used as an albedo elsewhere from becoming linear data.
                image = image.copy()
                image.colorspace_settings.name = 'Non-Color'
                texture = nodes.new('ShaderNodeTexImage')
                texture.image = image
                normal = nodes.new('ShaderNodeNormalMap')
                normal.inputs['Strength'].default_value = strength
                links.new(texture.outputs['Color'], normal.inputs['Color'])
                links.new(normal.outputs['Normal'], shader.inputs['Normal'])
                copies[original] = material
            slot.material = copies[original]
    print('HERON_OBJ_IMPORT PASS', len(imported), 'objects,', len(copies), 'normal mapped materials')
    return imported


if __name__ == '__main__':
    import_heron_obj(Path(__file__).with_name(__OBJ_FILE__))
